// UpdateInput changes a subscription. A nil field keeps the plan or quantity the subscription is heading to: its pending
// change if it has one, otherwise its current one.
type UpdateInput struct {
	PlanID   *string
	Quantity *int
}

// Update changes a subscription's plan or quantity. A subscription's value is its plan's unit amount times its quantity.
// An upgrade applies at once and is billed for the rest of the current period. A trialing subscription's change applies at
// once and is not billed. A downgrade does not apply now: it is pending until the next renewal. A change that keeps the
// value applies at once and is not billed.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
	}
	plans := map[string]store.Plan{}
	for _, p := range s.Store.Plans(orgID) {
		plans[p.ID] = p
	}
	now := s.Clock.Now()
	var proration *store.Invoice
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return ErrCanceled
		}
		from, ok := plans[sub.PlanID]
		if !ok {
			return store.ErrNotFound
		}
		toPlanID, toQuantity := sub.PlanID, sub.Quantity
		if sub.PendingPlanID != nil {
			toPlanID = *sub.PendingPlanID
		}
		if sub.PendingQuantity != nil {
			toQuantity = *sub.PendingQuantity
		}
		if in.PlanID != nil {
			toPlanID = *in.PlanID
		}
		if in.Quantity != nil {
			toQuantity = *in.Quantity
		}
		if toQuantity <= 0 {
			return fmt.Errorf("%w: the quantity must be at least 1", store.ErrInvalid)
		}
		to, ok := plans[toPlanID]
		if !ok {
			return store.ErrNotFound
		}
		if from.UsageType == store.Metered || to.UsageType == store.Metered || from.Currency != to.Currency || from.Interval != to.Interval {
			return ErrIncompatiblePlan
		}
		oldValue, newValue := from.UnitAmount*int64(sub.Quantity), to.UnitAmount*int64(toQuantity)
		if sub.Status != store.Trialing && newValue < oldValue {
			sub.PendingPlanID, sub.PendingQuantity = &toPlanID, &toQuantity
			return nil
		}
		if sub.Status != store.Trialing && newValue > oldValue {
			remaining := sub.CurrentPeriodEnd.Sub(now)
			length := sub.CurrentPeriodEnd.Sub(sub.CurrentPeriodStart)
			proration = &store.Invoice{OrgID: orgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: from.Currency,
				Lines:           prorationLines(from, to, oldValue, newValue, remaining, length),
				DiscountPercent: sub.DiscountPercent}
		}
		sub.PlanID, sub.Quantity = toPlanID, toQuantity
		sub.PendingPlanID, sub.PendingQuantity = nil, nil
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.updated", sub)
	if proration == nil {
		return sub, nil
	}
	paid, err := s.issue(ctx, *proration)
	if err != nil {
		return sub, err
	}
	if !paid {
		sub, err = s.setStatus(ctx, sub, store.PastDue)
	}
	return sub, err
}

// prorationLines are the two lines of an upgrade's invoice: the unused time on the old plan as a credit, and the remaining
// time on the new plan. Both are the share of the value that the rest of the current period is of its whole length.
func prorationLines(from, to store.Plan, oldValue, newValue int64, remaining, length time.Duration) []store.Line {
	left, whole := math.Max(remaining.Seconds(), 0), length.Seconds()
	left = math.Min(left, whole)
	unused := math.Round(float64(oldValue) * left / whole)
	rest := math.Round(float64(newValue) * left / whole)
	return []store.Line{
		{Description: "Unused time on " + from.Name, Quantity: 1, UnitAmount: -int64(unused)},
		{Description: "Remaining time on " + to.Name, Quantity: 1, UnitAmount: int64(rest)},
	}
}

